window.getStudentAddress = function(roll) {
    if (!roll) return null;
    const cleanRoll = roll.trim().toUpperCase();
    const student = window.MLRITM_STUDENTS ? window.MLRITM_STUDENTS[cleanRoll] : null;

    // 1. Check user-saved custom address in localStorage
    try {
        const stored = localStorage.getItem("mlritm_addr_" + cleanRoll);
        if (stored) {
            const parsed = JSON.parse(stored);
            return {
                ...parsed,
                hasAddress: true,
                isCustom: true
            };
        }
    } catch(e) {}

    // 2. Check verified addresses registry
    if (window.VERIFIED_STUDENT_ADDRESSES && window.VERIFIED_STUDENT_ADDRESSES[cleanRoll]) {
        const v = window.VERIFIED_STUDENT_ADDRESSES[cleanRoll];
        const formatted = `${v.doorNo ? v.doorNo + ', ' : ''}${v.street ? v.street + ', ' : ''}${v.town ? v.town + ', ' : ''}${v.district ? v.district + ', ' : ''}${v.state || 'Telangana'}${v.pincode ? ' - ' + v.pincode : ''}`;
        return {
            hasAddress: true,
            doorNo: v.doorNo,
            street: v.street,
            town: v.town,
            mandal: v.mandal,
            district: v.district,
            state: v.state,
            pincode: v.pincode,
            formatted: formatted,
            source: v.source,
            isVerified: true,
            father_mobile: v.fatherMobile || (student ? student.father_phone : ""),
            student_mobile: v.studentMobile || (student ? student.phone : "")
        };
    }

    // 3. Fallback: Residential address not yet synced from ERP.
    // NOTE: College campus address (Dundigal 500043) is strictly NOT used as student home address.
    return {
        hasAddress: false,
        status: "not_synced",
        message: "Home address not synced from Anvaya ERP profile",
        formatted: null,
        father: student ? (student.father || "") : "",
        father_mobile: student ? (student.father_phone || "") : "",
        student_mobile: student ? (student.phone || "") : "",
        caste: student ? (student.caste || "") : "",
        category: student ? (student.cat || "") : "",
        isVerified: false
    };
};

window.saveStudentAddress = function(roll, addressObj) {
    if (!roll) return false;
    const cleanRoll = roll.trim().toUpperCase();
    try {
        addressObj.isCustom = true;
        addressObj.hasAddress = true;
        if (!addressObj.formatted) {
            const parts = [addressObj.doorNo, addressObj.street, addressObj.town, addressObj.district, addressObj.state].filter(Boolean);
            addressObj.formatted = parts.join(", ") + (addressObj.pincode ? ` - ${addressObj.pincode}` : "");
        }
        localStorage.setItem("mlritm_addr_" + cleanRoll, JSON.stringify(addressObj));
        return true;
    } catch(e) {
        console.error("Error saving address:", e);
        return false;
    }
};
